End FPX_2.

Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).
Section FPX_3. Context {fx : PropExec.FPState}.

Definition in_ivs (z : Z) (l : list (word * word)) : bool := ltac2:(Rpl.RP.run_k (rplG ()) 2 "S4;A1;o3;Y6;00;A1;i75;#0;A2;i74;#1;#1;A2;k2;#0;A3;k79;#1;#1;r1;Lz;Ri5;Ll;RA1;i35;#2;A3;k76;#2;Liv;R#2;A2;k77;A2;k78;#3;r3;A2;k80;r3;A2;k9;#3;A2;k2;#0;A3;k81;#1;#1;r1;r1;").

Definition in_hull (A : atable) (z : Z) : bool := ltac2:(Rpl.RP.run_k (rplG ()) 2 "S0;LA;Ri82;Lz;Ri5;A2;k77;A2;k78;A1;k83;r2;r1;A2;k80;r1;A1;k84;r2;").

Definition iv_disjoint (p q : word * word) : Prop := ltac2:(Rpl.RP.run_k (rplG ()) 2 "S5;A1;o3;Y6;00;A1;i75;#0;A2;i74;#1;#1;A2;k2;#0;A3;k79;#1;#1;r2;A2;k2;#0;A3;k79;#1;#1;r1;Lp;R#2;Lq;R#2;A2;i85;A2;k11;A2;k9;#3;A2;k2;#0;A3;k81;#1;#1;r2;#4;A2;k11;A2;k9;#4;A2;k2;#0;A3;k81;#1;#1;r1;#3;").
Inductive seps : list (word * word) -> Prop :=
| seps_nil : seps []
| seps_cons : forall p l, Forall (iv_disjoint p) l -> seps l -> seps (p :: l).

Fixpoint sum_sizes (l : list (word * word)) : Z :=
  match l with [] => 0 | iv :: r => bv_unsigned (snd iv) + sum_sizes r end.

Definition cfg_of (SEGS : list Segment) (R : bvmap 5 word) (p : Z) (M : word -> option byte) (model : Model) : config := ltac2:(Rpl.RP.run_k (rplG ()) 5 "S3;A1;o3;Y6;00;A1;i75;#0;Y3;0;LSEGS;RA1;i35;i86;LR;RA2;k87;A1;o3;Y2;1;#1;Lp;Ri5;LM;RP~R#1;A1;i88;A1;i75;A1;o3;#2;Lmodel;Ri89;A2;o90;A5;k91;vfx;r4;A2;k92;#0;r3;r2;A1;k93;r5;r1;").

Section Sound.
Variable SEGS : list Segment.
Variable scfg : SpuriousCfg.
Variable IT : itab.
Hypothesis IT_ok : itab_sound SEGS IT.
Variable A : atable.
Variable nx0 : nat.
Variable LIMIT : Z.
Variable HS : nat -> option acs.

Variable XN : nat -> list expr -> acs -> option acs.
Variable XE : nat -> list expr -> acs -> option (Z * list spiece * acs).
Variable XB : nat -> list expr -> acs -> option (acs * acs).
Variable XON : xnode -> bool.

Hypothesis SEGS_wx : wx_segs_nowrap SEGS.
Hypothesis SEGS_in_hull : forall a : word, in_hull A (bv_unsigned a) = false -> find_segment SEGS (bv_unsigned a) 1 = None.

Definition res_len_ok : Prop := ltac2:(Rpl.RP.run_k (rplG ()) 0 "S1;A1;i75;A1;o3;Y6;00;A3;i15;i94;A2;k95;A2;i74;#0;#0;A1;k96;vSEGS;A1;k97;vA;").
Definition hull_ok : Prop := ltac2:(Rpl.RP.run_k (rplG ()) 0 "S3;A1;k83;vA;A1;o8;Y12;000;A1;k84;vA;A2;i19;A2;k11;o12;#0;A2;i19;A3;i15;i5;A2;k16;#0;#1;o12;A2;i19;A3;i15;i5;A2;k16;#2;#1;o12;A2;k11;#2;k98;").
Definition shadow_ok : Prop := ltac2:(Rpl.RP.run_k (rplG ()) 0 "S2;A1;k99;vA;Y1;0;A2;i19;A2;k11;o12;#0;A2;k11;#0;A2;k100;A1;o8;#1;A1;o8;Y5;0f;").
Hypothesis RES_len : res_len_ok.
Hypothesis RES_hull : Forall (fun iv => img_lo A <= bv_unsigned (fst iv) /\ bv_unsigned (fst iv) + bv_unsigned (snd iv) <= img_hi A) (segments_reserved SEGS).
Hypothesis HULL_ok : hull_ok.
Hypothesis SHADOW_ok : shadow_ok.

Variable SINV : env -> (word -> option byte) -> Prop.
Variable argH : env -> word -> bool.
Hypothesis argH_high : forall E (a : word), argH E a = true -> CEIL <= bv_unsigned a.
Hypothesis argH_agree : forall E E' (a : word), env_agree nx0 E E' -> argH E a = argH E' a.
Hypothesis SINV_frame : forall E M M', (forall a, argH E a = true -> M' a = M a) -> SINV E M -> SINV E M'.
Hypothesis SINV_agree : forall E E' M, env_agree nx0 E E' -> SINV E M -> SINV E' M.

Variable HOLES : nat -> env -> Fs.Fs -> TSet.
Hypothesis HOLES_agree : forall h E E' fs, env_agree nx0 E E' -> HOLES h E fs = HOLES h E' fs.
Hypothesis HOLES_nil : forall h E fs, HOLES h E fs [].

Variable FS0 : Fs.Fs.

Variable KC : nat.

#[local] Notation CHECK := (AP.check SEGS IT A nx0 LIMIT XN XE XB XON HS KC).

#[local] Notation cfg := (cfg_of SEGS).

Definition Wz (fd : Z) (bs : list Z) : list event := ltac2:(Rpl.RP.run_k (rplG ()) 2 "S1;Y3;0;Lfd;Ri5;Lbs;RA1;i35;i5;A4;k101;i5;i102;Lz;Ri5;A2;o103;A2;k92;A1;o3;Y6;00;r3;A2;k92;A1;o3;#0;r1;r1;").

Definition piece_den (E : env) (p : spiece) : list byte := ltac2:(Rpl.RP.run_k (rplG ()) 2 "S2;A1;o3;Y3;0;A1;i75;#0;LE;Ri0;Lp;Ri104;m104;RNLp;Ri104;A1;i35;#1;r1;2;Lbs;RA1;i35;i5;A4;k101;i5;#1;A1;k92;#0;r1;Lk;Ri94;A2;k105;r3;r1;").
Definition Wp (E : env) (fd : Z) (ps : list spiece) : list event := ltac2:(Rpl.RP.run_k (rplG ()) 3 "S2;Y3;0;A1;i75;A1;o3;#0;LE;Ri0;Lfd;Ri5;Lps;RA1;i35;i104;A4;k101;#1;i102;A1;o103;A2;k92;A1;o3;Y6;00;r2;A4;k106;i104;#1;A1;k107;r3;r1;").

Fixpoint sd (D : TSet) (E : env) (fs : Fs.Fs) (s : shape) : TSet :=
  match s with
  | SNil => t_nil
  | SExit c => t_exit (Z_to_bv 64 c) fs
  | SEmitP fd ps s' => t_emit (Wp E fd ps) (sd D E fs s')
  | SAlt2 a b => t_alt2 (sd D E fs a) (sd D E fs b)
  | SCase e mid s1 s2 => if (bv_unsigned (edenot E e) <=? mid)%Z then sd D E fs s1 else sd D E fs s2
  | SHole h => HOLES h E fs
  | SNext => D
  end.

